def reset():
    global _status, _data
    _status = "idle"
    _data = None


def load(source):
    """Load data from source. Sets status on success only.

    This version safely handles None, empty iterables, and iterables
    without __len__ (e.g. generators) by materializing the source into
    a list and always updating _status so it reflects THIS call's outcome.
    """
    global _status, _data

    if source is None:
        _data = []
        _status = "empty"
        return _data

    # Try to convert to list to handle generators and other iterables
    try:
        lst = list(source)
    except TypeError:
        # Not iterable: treat as empty input
        _data = []
        _status = "empty"
        return _data

    if len(lst) > 0:
        _data = lst
        _status = "loaded"
    else:
        _data = []
        _status = "empty"

    return _data


def get_status():
    return _status


def get_data():
    return _data


def validate_format(data):
    """Distractor: checks data format, unrelated to bug."""
